package net.civeira.phylax.features.document.templatevariable.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ValueVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property value of template variable ")
  void test_value_v_o_builder() {
    Assertions.assertFalse(ValueVO.nullValue().getValue().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ValueVO.tryFrom(null).getValue().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ValueVO.from("one").getValue().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ValueVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ValueVO.from("one").toString());
  }
}
